import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-DrdKnICy.js";var i=JSON.parse(`{"path":"/english/vocabulary/animal-protection/habitat-captivity-and-protection/","title":"CH3.7 栖息、圈养与保护 | 英语","lang":"zh-CN","frontmatter":{"title":"CH3.7 栖息、圈养与保护","createTime":"2026-11-20T10:00:00.000Z","permalink":"/english/vocabulary/animal-protection/habitat-captivity-and-protection/"},"readingTime":{"minutes":32.6,"words":9781},"git":{"createdTime":1795161551000},"filePathRelative":"english/vocabulary/animal-protection/7.habitat-captivity-and-protection.md","headers":[],"bulletin":false}`),a={name:`7.habitat-captivity-and-protection.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="habitat" tabindex="-1"><a class="header-anchor" href="#habitat"><span>Habitat</span></a></h2><p class="vc-meta"><strong>/ˈhæbɪtæt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>栖息地，（动植物的）生境</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>natural habitat</td><td>自然栖息地</td></tr><tr><td>habitat loss</td><td>栖息地丧失</td></tr><tr><td>habitat destruction</td><td>栖息地破坏</td></tr><tr><td>restore a habitat</td><td>恢复栖息地</td></tr><tr><td>a habitat for ...</td><td>……的栖息地</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows how much natural habitat was lost to development in each region.</p><blockquote><p>该地图显示了各地区有多少自然栖息地因开发而丧失。</p></blockquote><p><strong>Writing Task 2</strong> Habitat loss is the single greatest threat to biodiversity, and it is caused less by hunting than by the quiet conversion of land to farmland and housing.</p><blockquote><p>栖息地丧失是生物多样性面临的最大威胁，其成因与其说是捕猎，不如说是土地被悄悄改作农田与住宅。</p></blockquote><p><strong>Speaking</strong> The pond behind the school is the last habitat for frogs in this area, and they want to build a car park on it.</p><blockquote><p>学校后面的池塘是本地区蛙类最后的栖息地，而他们想在上面建停车场。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>environment</td><td>环境</td><td>更泛，含气候、社会因素</td></tr><tr><td>ecosystem</td><td>生态系统</td><td>强调功能整体，不只空间</td></tr><tr><td>home range</td><td>活动范围</td><td>指个体活动区域，非生境类型</td></tr><tr><td>niche</td><td>生态位</td><td>强调功能角色，不是物理空间</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>habitare</em>（居住），源自 <em>habere</em>（持有）</li><li><strong>Family:</strong> inhabit 栖息于 / inhabitant 居民 / habitable 可居住的 / habit 习惯（同源）</li><li><strong>Memory Tip:</strong> habit（习惯）与 habitat（栖息地）同源——都是&quot;长期待着&quot;的地方或方式。一个人&quot;住惯了&quot;是 habit，动物&quot;住的地方&quot;是 habitat。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>habitat 指&quot;某类生境&quot;，不是&quot;某只动物的家&quot;：说 <s>the bird&#39;s habitat is that tree</s> 不准确，应用 nest / home range。</li><li>拼写 habi-tat，不是 <s>habitate</s>。</li><li>&quot;栖息地丧失&quot;是 <strong>habitat loss</strong>，不用 <s>habitat lost</s>。</li></ul></div><div class="vocab-card"><h2 id="nest" tabindex="-1"><a class="header-anchor" href="#nest"><span>Nest</span></a></h2><p class="vc-meta"><strong>/nest/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>巢，窝</li><li>（喻）安乐窝；巢穴（犯罪等的据点）</li><li>筑巢（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>build a nest</td><td>筑巢</td></tr><tr><td>a bird&#39;s nest</td><td>鸟巢</td></tr><tr><td>nest in ...</td><td>在……筑巢</td></tr><tr><td>leave the nest</td><td>离巢；离家独立</td></tr><tr><td>nesting season</td><td>筑巢期</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the number of nests counted in each part of the reserve.</p><blockquote><p>该图显示了保护区内各区域统计到的巢数。</p></blockquote><p><strong>Writing Task 2</strong> Logging during the nesting season destroys not just nests but the entire generation of chicks inside them.</p><blockquote><p>在筑巢季伐木，毁掉的不只是巢，还有巢里整整一代雏鸟。</p></blockquote><p><strong>Speaking</strong> A swallow has built a nest right above our door, and now nobody wants to use that entrance.</p><blockquote><p>一只燕子正好在我们门上方筑了巢，现在没人愿意走那个门。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>den</td><td>兽穴</td><td>指狐、熊等的洞穴</td></tr><tr><td>burrow</td><td>地洞</td><td>兔、鼹鼠挖的地下通道</td></tr><tr><td>hive</td><td>蜂巢</td><td>专指蜂群住所</td></tr><tr><td>lair</td><td>巢穴</td><td>多指猛兽，带危险感</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>nest</em>，与拉丁 <em>nidus</em>（巢）同源</li><li><strong>Family:</strong> nest 巢 / nestling 雏鸟 / nest egg 储备金 / empty nester 空巢父母</li><li><strong>Memory Tip:</strong> &quot;empty nest&quot;（空巢）是常见社会话题词——孩子离家后父母的处境。用这个熟悉的说法记住 nest 的&quot;家&quot;义。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不同动物巢穴专名不同：den（兽穴）、burrow（地洞）、hive（蜂巢）、lair（猛兽巢穴）。</li><li>&quot;筑巢&quot;是 build a nest，也可用动词 nest：The birds <strong>nest</strong> in the cliffs. ✔</li><li>拼写 nest，别与 <s>next</s> 混。</li></ul></div><div class="vocab-card"><h2 id="hive" tabindex="-1"><a class="header-anchor" href="#hive"><span>Hive</span></a></h2><p class="vc-meta"><strong>/haɪv/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>蜂箱，蜂巢</li><li>蜂群</li><li>繁忙的场所（喻：a hive of activity）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a bee hive</td><td>蜂箱</td></tr><tr><td>hive products</td><td>蜂产品</td></tr><tr><td>a hive of activity</td><td>一片繁忙</td></tr><tr><td>hive off</td><td>剥离（业务）</td></tr><tr><td>hive mind</td><td>群体思维</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the internal structure of a hive and where the honey is stored.</p><blockquote><p>该示意图展示了蜂箱的内部结构以及蜂蜜储存的位置。</p></blockquote><p><strong>Writing Task 2</strong> Without wild pollinators, farmers rent hives, which works until disease sweeps through the colonies they depend on.</p><blockquote><p>没有野生传粉者，农民只能租用蜂箱；而这个办法会一直有效，直到病害席卷他们所依赖的蜂群。</p></blockquote><p><strong>Speaking</strong> The market on Saturday is a hive of activity — you can barely move.</p><blockquote><p>周六的市场一片繁忙，几乎走不动。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>colony</td><td>群体</td><td>强调蜂群这一社会单位</td></tr><tr><td>nest</td><td>巢</td><td>泛指鸟兽的巢，不限于蜂</td></tr><tr><td>apiary</td><td>蜂场</td><td>指人工养蜂的场地</td></tr><tr><td>swarm</td><td>蜂群</td><td>指离开原巢分出的群</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>hȳf</em>（蜂巢）</li><li><strong>Family:</strong> hive 蜂巢 / beehive 蜂箱 / hive mind 群体思维 / hives 荨麻疹（同形不同源）</li><li><strong>Memory Tip:</strong> &quot;a hive of activity&quot; 形容人多忙碌的场所——像蜂箱一样嗡嗡不停。把这条比喻记住，hive 的&quot;繁忙&quot;引申义自然就懂了。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>蜂群用 <strong>colony</strong> 更准确，hive 多指&quot;箱/巢&quot;这个实体。</li><li>&quot;剥离业务&quot;是 hive <strong>off</strong>，带 off。</li><li>拼写 hive，别与 <s>hove</s>（heave 的过去式）混。</li></ul></div><div class="vocab-card"><h2 id="cell" tabindex="-1"><a class="header-anchor" href="#cell"><span>Cell</span></a></h2><p class="vc-meta"><strong>/sel/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>细胞</li><li>小室，牢房；电池</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a single cell</td><td>单个细胞</td></tr><tr><td>cell division</td><td>细胞分裂</td></tr><tr><td>cell membrane</td><td>细胞膜</td></tr><tr><td>a prison cell</td><td>牢房</td></tr><tr><td>solar cell</td><td>太阳能电池</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how a single cell divides into two identical cells.</p><blockquote><p>该示意图展示了单个细胞如何分裂成两个相同的细胞。</p></blockquote><p><strong>Writing Task 2</strong> Every living thing is built from cells, and the instructions for building them are written in the same four-letter code across all species.</p><blockquote><p>每个生物都由细胞构成，而构建细胞的指令在所有物种中都用同一套四字母编码书写。</p></blockquote><p><strong>Speaking</strong> Our biology teacher said the cell is the smallest unit of life and then spent forty minutes proving it.</p><blockquote><p>生物老师说细胞是生命的最小单位，然后花了四十分钟证明这一点。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>unit</td><td>单位</td><td>泛指，无生物学含义</td></tr><tr><td>chamber</td><td>腔室</td><td>建筑或解剖的空间</td></tr><tr><td>compartment</td><td>隔间</td><td>强调分隔，多用于结构</td></tr><tr><td>battery</td><td>电池</td><td>只在&quot;电池&quot;义上对应</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>cella</em>（小房间）</li><li><strong>Family:</strong> cell 细胞；牢房 / cellar 地窖 / cellular 细胞的；蜂窝式的 / cellulite 脂肪团</li><li><strong>Memory Tip:</strong> cella 是&quot;小房间&quot;——细胞是生命体的&quot;小房间&quot;，牢房也是&quot;小房间&quot;，手机 cell phone 的蜂窝网络同样由一个个&quot;小格子&quot;组成。三义一源。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>生物学语境中 cell 是可数名词，泛指时用复数：Cells <strong>divide</strong>. ✔</li><li>拼写 cell 双 l：ce<strong>ll</strong> ✔</li><li>&quot;蜂窝网络&quot;是 cellular network，用形容词形式。</li></ul></div><div class="vocab-card"><h2 id="cage" tabindex="-1"><a class="header-anchor" href="#cage"><span>Cage</span></a></h2><p class="vc-meta"><strong>/keɪdʒ/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>笼子</li><li>把……关进笼子；限制自由（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a bird cage</td><td>鸟笼</td></tr><tr><td>battery cage</td><td>层架式鸡笼</td></tr><tr><td>keep animals in cages</td><td>把动物关在笼中</td></tr><tr><td>a cage-free system</td><td>无笼饲养</td></tr><tr><td>rattle the cage</td><td>搅动局面</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the space available per bird in caged and cage-free systems.</p><blockquote><p>该图比较了笼养与无笼饲养两种方式下每只鸡可用的空间。</p></blockquote><p><strong>Writing Task 2</strong> A cage that prevents an animal from performing its natural behaviour does not merely restrict it; it produces abnormal behaviour that no amount of food can compensate for.</p><blockquote><p>阻止动物表现自然行为的笼子不只是限制它，还会催生异常行为，这是多少食物都弥补不了的。</p></blockquote><p><strong>Speaking</strong> The parrot&#39;s cage is open all day, but it only comes out to sit on the fridge.</p><blockquote><p>鹦鹉的笼子全天开着，但它只出来站在冰箱上。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>enclosure</td><td>围场</td><td>动物园用词，空间较大</td></tr><tr><td>pen</td><td>圈</td><td>家畜围栏，多在户外</td></tr><tr><td>crate</td><td>笼箱</td><td>运输用，密闭</td></tr><tr><td>coop</td><td>鸡笼</td><td>专用于家禽</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>cavea</em>（空腔、围栏），源自 <em>cavus</em>（空的）</li><li><strong>Family:</strong> cage 笼 / cave 洞穴（同源&quot;空&quot;）/ cavity 腔 / excavate 挖掘（&quot;挖空&quot;）</li><li><strong>Memory Tip:</strong> cavus 是&quot;空&quot;：cage 是&quot;空心的框&quot;、cave 是&quot;空的山洞&quot;、excavate 是&quot;挖空&quot;。一条词根把&quot;空&quot;分给四个词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>动物园的&quot;场馆&quot;用 <strong>enclosure</strong>，cage 常暗示空间狭小、带批评色彩。</li><li>动词 caged 作形容词：caged <strong>birds</strong> ✔</li><li>拼写 cage，注意 g 后接 e 读 /dʒ/。</li></ul></div><div class="vocab-card"><h2 id="stable" tabindex="-1"><a class="header-anchor" href="#stable"><span>Stable</span></a></h2><p class="vc-meta"><strong>/ˈsteɪbl/</strong> · noun · 名词 / adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>马厩，牲口棚（名词）</li><li>稳定的，稳固的（形容词）</li><li>稳定的（化学、医学）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a stable population</td><td>稳定的种群</td></tr><tr><td>remain stable</td><td>保持稳定</td></tr><tr><td>stable conditions</td><td>稳定的条件</td></tr><tr><td>muck out the stable</td><td>清理马厩</td></tr><tr><td>a stable isotope</td><td>稳定同位素</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows that the population remained stable for two decades before declining sharply.</p><blockquote><p>该图显示该种群在急剧下降前有二十年保持稳定。</p></blockquote><p><strong>Writing Task 2</strong> A stable population is not necessarily a healthy one: it may simply be the residue left after the habitat has already been degraded.</p><blockquote><p>稳定的种群未必是健康的种群：它可能只是栖息地退化后留下的残余。</p></blockquote><p><strong>Speaking</strong> The horses are in the stable at night and out in the field by seven.</p><blockquote><p>马晚上在马厩里，七点就放到牧场去了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>steady</td><td>平稳的</td><td>强调变化小、持续</td></tr><tr><td>constant</td><td>恒定的</td><td>强调数值不变</td></tr><tr><td>barn</td><td>谷仓</td><td>存粮或养畜的建筑，非专指马</td></tr><tr><td>firm</td><td>坚固的</td><td>强调结构牢固</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>stabilis</em>（站得住的），源自 <em>stare</em>（站立）</li><li><strong>Family:</strong> stability 稳定性 / stabilise 使稳定 / establish 建立 / stage 舞台（同源&quot;站&quot;）</li><li><strong>Memory Tip:</strong> 词根 sta- 是&quot;站&quot;：stable 站得稳、establish 立起来、stage 站的地方。一个&quot;站&quot;字打通一整族词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词&quot;马厩&quot;与形容词&quot;稳定的&quot;同形，靠位置判断：in the <strong>stable</strong> / a <strong>stable</strong> population。</li><li>动词是 <strong>stabilise</strong>（英式）/ stabilize（美式），不是 <s>stable</s> 作动词。</li><li>拼写 sta-ble，注意 -able。</li></ul></div><div class="vocab-card"><h2 id="barn" tabindex="-1"><a class="header-anchor" href="#barn"><span>Barn</span></a></h2><p class="vc-meta"><strong>/bɑːn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>谷仓，粮仓；牲口棚</li><li>（美式）大型车库式建筑</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a barn owl</td><td>仓鸮</td></tr><tr><td>hay barn</td><td>干草棚</td></tr><tr><td>a barn conversion</td><td>谷仓改建的住宅</td></tr><tr><td>barn door</td><td>谷仓大门</td></tr><tr><td>barn swallow</td><td>家燕</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the farm buildings, including the barn and the cattle shed.</p><blockquote><p>该地图显示了农场的建筑，包括谷仓与牛棚。</p></blockquote><p><strong>Writing Task 2</strong> Old barns are among the most important wildlife sites left in farmland, sheltering bats, owls and insects that have nowhere else to go.</p><blockquote><p>老旧谷仓是农田中仅存的最重要野生动物据点之一，为无处可去的蝙蝠、猫头鹰与昆虫提供庇护。</p></blockquote><p><strong>Speaking</strong> They converted the barn into a house and kept the original beams, which look great and cost a fortune.</p><blockquote><p>他们把谷仓改成了住宅，保留了原来的梁，看着很棒，也很费钱。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>shed</td><td>棚屋</td><td>小型简易建筑</td></tr><tr><td>stable</td><td>马厩</td><td>专养马匹</td></tr><tr><td>granary</td><td>粮仓</td><td>专储存谷物</td></tr><tr><td>warehouse</td><td>仓库</td><td>大型商用储存建筑</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>bern</em>（储存大麦之处），<em>bere</em>（大麦）+ <em>ern</em>（房屋）</li><li><strong>Family:</strong> barn 谷仓 / barn owl 仓鸮 / barnyard 场院 / barnstorm 巡回演出</li><li><strong>Memory Tip:</strong> 原义是&quot;大麦的房子&quot;——bere（大麦）+ ern（屋）。仓鸮（barn owl）就住在谷仓里，两个词天然绑定。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>barn 是&quot;谷仓&quot;，马厩是 <strong>stable</strong>，两者不同。</li><li>拼写 barn，别与 <s>bran</s>（麸皮）混。</li><li>&quot;谷仓改建住宅&quot;是 <strong>barn conversion</strong>，英式固定说法。</li></ul></div><div class="vocab-card"><h2 id="hedge" tabindex="-1"><a class="header-anchor" href="#hedge"><span>Hedge</span></a></h2><p class="vc-meta"><strong>/hedʒ/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>树篱，绿篱</li><li>防备，对冲（hedge against）</li><li>含糊其辞（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a hawthorn hedge</td><td>山楂树篱</td></tr><tr><td>trim the hedge</td><td>修剪树篱</td></tr><tr><td>hedge against ...</td><td>防范……</td></tr><tr><td>hedge funds</td><td>对冲基金</td></tr><tr><td>hedgerows</td><td>田边树篱带</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows how hedgerows were removed to enlarge the fields between 1960 and 1990.</p><blockquote><p>该地图显示了 1960 至 1990 年间为扩大田块而被清除的树篱带。</p></blockquote><p><strong>Writing Task 2</strong> A hedgerow is a corridor, a larder and a nesting site at once, so removing it costs far more than the land it occupies.</p><blockquote><p>一条树篱同时是通道、食橱与巢址，因此清除它的代价远超它占用的那点土地。</p></blockquote><p><strong>Speaking</strong> The hedge between us and next door is the only reason we still speak to each other.</p><blockquote><p>我们和隔壁之间那道树篱，是我们还能说话的唯一原因。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>hedgerow</td><td>田边树篱</td><td>指农田间整条树篱，更专业</td></tr><tr><td>fence</td><td>栅栏</td><td>人造材料，非植物</td></tr><tr><td>barrier</td><td>屏障</td><td>泛称，不限材质</td></tr><tr><td>shrubbery</td><td>灌木丛</td><td>观赏性栽植，非边界功能</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>hecg</em>（篱笆）</li><li><strong>Family:</strong> hedge 树篱 / hedgerow 树篱带 / hedgehog 刺猬（&quot;篱笆猪&quot;）/ hedging 模糊措辞</li><li><strong>Memory Tip:</strong> hedgehog（刺猬）字面是&quot;篱笆猪&quot;——住在树篱里的猪。一个词把&quot;树篱&quot;与&quot;刺猬&quot;同时记住，非常高效。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>农业景观里整条树篱更常说 <strong>hedgerow</strong>，hedge 指其中一段。</li><li>&quot;防范风险&quot;是 hedge <strong>against</strong> sth，介词固定。</li><li>拼写 hedge，注意 dg 读 /dʒ/。</li></ul></div><div class="vocab-card"><h2 id="barrier" tabindex="-1"><a class="header-anchor" href="#barrier"><span>Barrier</span></a></h2><p class="vc-meta"><strong>/ˈbæriə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>屏障，障碍物</li><li>障碍，隔阂（抽象的）</li><li>屏障礁（地理）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a physical barrier</td><td>物理屏障</td></tr><tr><td>a barrier to ...</td><td>……的障碍</td></tr><tr><td>break down barriers</td><td>打破隔阂</td></tr><tr><td>a safety barrier</td><td>安全护栏</td></tr><tr><td>the Great Barrier Reef</td><td>大堡礁</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the barriers built along the river to prevent flooding.</p><blockquote><p>该地图显示了沿河修建的防洪屏障。</p></blockquote><p><strong>Writing Task 2</strong> Roads and fences fragment habitat into islands, and for a species that will not cross open ground, a narrow barrier is as final as an ocean.</p><blockquote><p>道路与围栏把栖息地割裂成孤岛，对不愿穿越开阔地的物种来说，一道窄屏障与一片海洋同样不可逾越。</p></blockquote><p><strong>Speaking</strong> The language barrier was real, but pointing at things worked surprisingly well.</p><blockquote><p>语言障碍确实存在，但指手画脚效果出奇地好。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>obstacle</td><td>障碍</td><td>强调妨碍前进，多用于抽象</td></tr><tr><td>fence</td><td>围栏</td><td>具体实物，功能明确</td></tr><tr><td>hindrance</td><td>阻碍</td><td>书面，语气较轻</td></tr><tr><td>wall</td><td>墙</td><td>只指实体结构</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>barriere</em>，源自 <em>barre</em>（横杠）</li><li><strong>Family:</strong> barrier 屏障 / bar 横杆；酒吧 / barrage 拦河坝；连续炮击 / debar 排除</li><li><strong>Memory Tip:</strong> 词根 barre 是&quot;横杠&quot;——一条横杠就是最简单的屏障。同族的 bar（酒吧吧台就是一道横杠）、barrage（拦河坝）都围绕&quot;拦住&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;……的障碍&quot;用 <strong>a barrier to</strong> + 名词：a barrier <strong>to</strong> migration ✔ / <s>a barrier of migration</s> ✘</li><li>拼写 bar-rier，双 r。</li><li>抽象义（语言、文化障碍）比物理义更常用于大作文。</li></ul></div><div class="vocab-card"><h2 id="bar" tabindex="-1"><a class="header-anchor" href="#bar"><span>Bar</span></a></h2><p class="vc-meta"><strong>/bɑː(r)/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>条，棒（金属、木头的）</li><li>酒吧；吧台</li><li>栏杆，障碍</li><li>阻挡，禁止（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a bar of chocolate</td><td>一块巧克力</td></tr><tr><td>behind bars</td><td>在狱中</td></tr><tr><td>bar sb from ...</td><td>禁止某人……</td></tr><tr><td>a metal bar</td><td>金属条</td></tr><tr><td>the bar</td><td>律师界（英式）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how many visitors were barred from the reserve for feeding animals.</p><blockquote><p>该图显示了有多少游客因投喂动物而被禁止进入保护区。</p></blockquote><p><strong>Writing Task 2</strong> A few metal bars are all that separates a captive predator from the people who paid to see it, which is a strange kind of intimacy.</p><blockquote><p>几根金属栏杆就把一头圈养的捕食者与付钱来看它的人隔开，这是一种奇怪的距离感。</p></blockquote><p><strong>Speaking</strong> We waited at the bar for twenty minutes and then gave up and ordered at the table.</p><blockquote><p>我们在吧台等了二十分钟，然后放弃，改在桌上点单。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>rod</td><td>杆</td><td>细长的圆杆</td></tr><tr><td>barrier</td><td>屏障</td><td>强调阻挡功能</td></tr><tr><td>prohibit</td><td>禁止</td><td>正式法规用语</td></tr><tr><td>pub</td><td>酒馆</td><td>只对应&quot;酒吧&quot;义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>barre</em>（横杠）</li><li><strong>Family:</strong> bar 条；酒吧 / barrier 屏障 / barrel 桶 / barrage 拦阻</li><li><strong>Memory Tip:</strong> bar 的核心是&quot;一根横杠&quot;：横在门口就是禁止（bar sb from），横在吧台上就是酒吧，横在乐谱上就是小节线（bar）。一横多义。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;禁止某人做某事&quot;是 bar sb <strong>from doing</strong> sth，介词用 from。</li><li>&quot;在狱中&quot;是 behind <strong>bars</strong>，用复数。</li><li>拼写 bar，别与 <s>bare</s>（裸露的）混，两者同音。</li></ul></div><div class="vocab-card"><h2 id="prey" tabindex="-1"><a class="header-anchor" href="#prey"><span>Prey</span></a></h2><p class="vc-meta"><strong>/preɪ/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>猎物</li><li>捕食（prey on / upon）</li><li>折磨，困扰（prey on one&#39;s mind）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>prey on ...</td><td>捕食……</td></tr><tr><td>birds of prey</td><td>猛禽</td></tr><tr><td>fall prey to ...</td><td>成为……的牺牲品</td></tr><tr><td>easy prey</td><td>容易得手的目标</td></tr><tr><td>prey species</td><td>被食物种</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the prey species taken by the predator over one year.</p><blockquote><p>该图显示了该捕食者在一年中捕食的猎物物种。</p></blockquote><p><strong>Writing Task 2</strong> When a prey species loses its fear of humans, it stops being wild, and the change is usually irreversible.</p><blockquote><p>当被食物种不再惧怕人类时，它就不再是野生的了，而这种改变通常不可逆。</p></blockquote><p><strong>Speaking</strong> The cat brought in a bird and looked at us as if we should be grateful.</p><blockquote><p>猫叼回一只鸟，看我们的眼神像是在等我们道谢。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>quarry</td><td>猎物</td><td>书面，多用于狩猎语境</td></tr><tr><td>target</td><td>目标</td><td>泛称，无生物义</td></tr><tr><td>victim</td><td>受害者</td><td>强调受伤害，非捕食关系</td></tr><tr><td>game</td><td>猎物</td><td>特指可合法猎捕的鸟兽</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>praeda</em>（掠夺物）</li><li><strong>Family:</strong> prey 猎物 / predator 捕食者 / predate 捕食（动词）/ predatory 掠夺性的</li><li><strong>Memory Tip:</strong> prey 与 predator 同源——一个是&quot;被抢的&quot;，一个是&quot;抢的&quot;。成对记住，捕食关系就是一对词根的两端。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>prey 单复数同形：<s>preys</s> 一般不用作名词复数。</li><li>&quot;捕食&quot;是 prey <strong>on</strong>，不是及物直接跟宾语。</li><li>拼写 prey，别与 <s>pray</s>（祈祷）混，两者同音。</li></ul></div><div class="vocab-card"><h2 id="predator" tabindex="-1"><a class="header-anchor" href="#predator"><span>Predator</span></a></h2><p class="vc-meta"><strong>/ˈpredətə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>捕食者，掠食动物</li><li>掠夺者，剥削者（喻）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a natural predator</td><td>天敌</td></tr><tr><td>a top predator</td><td>顶级捕食者</td></tr><tr><td>predator and prey</td><td>捕食者与猎物</td></tr><tr><td>remove predators</td><td>移除天敌</td></tr><tr><td>a predator&#39;s territory</td><td>捕食者的领地</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows how the prey population changed after the predator was removed.</p><blockquote><p>该图显示了移除捕食者后猎物种群的变化。</p></blockquote><p><strong>Writing Task 2</strong> Removing a top predator does not simplify an ecosystem; it sets off a chain of effects that can take decades to become fully visible.</p><blockquote><p>移除顶级捕食者并不会简化生态系统，反而会触发一连串需要数十年才完全显现的效应。</p></blockquote><p><strong>Speaking</strong> The cat thinks it&#39;s a fearsome predator, and to a moth it absolutely is.</p><blockquote><p>猫觉得自己是可怕的捕食者，对一只蛾子来说它确实如此。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>hunter</td><td>猎手</td><td>强调主动搜寻，可指人</td></tr><tr><td>carnivore</td><td>食肉动物</td><td>按食性分类，不含&quot;捕猎&quot;义</td></tr><tr><td>raptor</td><td>猛禽</td><td>只指鸟类</td></tr><tr><td>attacker</td><td>攻击者</td><td>泛称，无生态含义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>praedator</em>（掠夺者），源自 <em>praeda</em>（掠夺物）</li><li><strong>Family:</strong> predator 捕食者 / prey 猎物 / predatory 掠夺性的 / predation 捕食行为</li><li><strong>Memory Tip:</strong> predatory pricing（掠夺性定价）是商业高频词——同一词根从&quot;捕食&quot;延伸到&quot;商业掠夺&quot;。看到 predatory 先想&quot;占便宜的强者&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 <strong>carnivore</strong> 不同：捕食者按行为定义，食肉动物按食性定义。</li><li>拼写 pred-ator，不是 <s>preditor</s>。</li><li>&quot;顶级捕食者&quot;是 <strong>apex / top predator</strong>，两种说法都常用。</li></ul></div><div class="vocab-card"><h2 id="victim" tabindex="-1"><a class="header-anchor" href="#victim"><span>Victim</span></a></h2><p class="vc-meta"><strong>/ˈvɪktɪm/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>受害者，牺牲品</li><li>（祭祀的）牺牲</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>fall victim to ...</td><td>成为……的受害者</td></tr><tr><td>the victims of ...</td><td>……的受害者</td></tr><tr><td>a road victim</td><td>交通事故遇难者</td></tr><tr><td>victim of circumstance</td><td>环境的受害者</td></tr><tr><td>innocent victim</td><td>无辜的受害者</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the number of road victims involving wildlife collisions in each region.</p><blockquote><p>该图显示了各地区涉及野生动物碰撞的交通事故伤亡人数。</p></blockquote><p><strong>Writing Task 2</strong> It is easy to present farmers as victims and conservationists as villains, but the conflict is really over who has the right to use land.</p><blockquote><p>把农民描述为受害者、把保护者描述为恶人很容易，但这场冲突的真正焦点是谁有权使用土地。</p></blockquote><p><strong>Speaking</strong> The victim of the whole business was the dog, who got blamed for everything.</p><blockquote><p>整件事的受害者是那条狗，什么都被怪到它头上。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>casualty</td><td>伤亡者</td><td>多用于事故、战争统计</td></tr><tr><td>prey</td><td>猎物</td><td>生态语境，不含&quot;受害&quot;义</td></tr><tr><td>sufferer</td><td>受苦者</td><td>多指疾病、长期困境</td></tr><tr><td>target</td><td>目标</td><td>强调被针对，未必然受伤</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>victima</em>（祭品）</li><li><strong>Family:</strong> victim 受害者 / victimise 使受害；歧视 / victimhood 受害者身份</li><li><strong>Memory Tip:</strong> 原义是&quot;祭品&quot;——被献出去的那一个。所以 victim 天生带&quot;无辜被牺牲&quot;的意味，写作为弱势群体发声时很常用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;成为受害者&quot;是 fall victim <strong>to</strong>，介词不能省。</li><li>拼写 vic-tim，不是 <s>victom</s>。</li><li>与 prey 区分：victim 强调受害，prey 强调被捕食。</li></ul></div><div class="vocab-card"><h2 id="captive" tabindex="-1"><a class="header-anchor" href="#captive"><span>Captive</span></a></h2><p class="vc-meta"><strong>/ˈkæptɪv/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>被关起来的，圈养的（形容词）</li><li>俘虏，囚徒（名词）</li><li>受制的（市场、听众等，喻）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>captive animals</td><td>圈养动物</td></tr><tr><td>captive breeding</td><td>圈养繁殖</td></tr><tr><td>hold sb captive</td><td>囚禁某人</td></tr><tr><td>a captive audience</td><td>无法离开的听众</td></tr><tr><td>in captivity</td><td>在圈养状态下</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the survival rates of captive-bred and wild-bred animals after release.</p><blockquote><p>该图比较了圈养繁殖与野生繁殖个体放归后的存活率。</p></blockquote><p><strong>Writing Task 2</strong> Captive breeding can save a species from extinction, but it cannot recreate the behaviour that animals learn only from living free.</p><blockquote><p>圈养繁殖能把一个物种从灭绝中拉回，却无法重建动物只有在自由生活中才能学到的行为。</p></blockquote><p><strong>Speaking</strong> The kids were a captive audience for my slideshow about whales, and they were very polite about it.</p><blockquote><p>孩子们被迫听我讲鲸鱼的幻灯片，他们表现得非常有礼貌。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>caged</td><td>关在笼中的</td><td>具体到笼子，带批评色彩</td></tr><tr><td>imprisoned</td><td>被囚禁的</td><td>多用于人，法律语境</td></tr><tr><td>confined</td><td>受限的</td><td>强调空间受限，不一定有人囚禁</td></tr><tr><td>domesticated</td><td>家养的</td><td>指长期驯化，非临时圈养</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>captivus</em>，源自 <em>capere</em>（抓取）</li><li><strong>Family:</strong> captive 被俘的 / capture 捕获 / capacity 容量（&quot;能装下&quot;）/ accept 接受</li><li><strong>Memory Tip:</strong> capere 是&quot;抓&quot;：captive 被抓的、capture 抓住、capacity 能装多少。一个&quot;抓&quot;字带出一组高频词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;在圈养中&quot;是 <strong>in captivity</strong>，用名词形式，不是 <s>in captive</s>。</li><li>captive 作名词指&quot;俘虏（人）&quot;，指动物时用形容词：captive <strong>animals</strong> ✔</li><li>拼写 cap-tive，不是 <s>captative</s>。</li></ul></div><div class="vocab-card"><h2 id="defensive" tabindex="-1"><a class="header-anchor" href="#defensive"><span>Defensive</span></a></h2><p class="vc-meta"><strong>/dɪˈfensɪv/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>防御性的，防守的</li><li>戒备的，易被冒犯的（人）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>defensive behaviour</td><td>防御行为</td></tr><tr><td>a defensive posture</td><td>防御姿态</td></tr><tr><td>on the defensive</td><td>处于防守状态</td></tr><tr><td>defensive mechanisms</td><td>防御机制</td></tr><tr><td>get defensive</td><td>变得戒备</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the defensive response of the animal when a predator approaches.</p><blockquote><p>该示意图展示了捕食者靠近时这种动物的防御反应。</p></blockquote><p><strong>Writing Task 2</strong> Bright coloration in frogs is defensive: it warns predators that the animal is poisonous rather than trying to hide.</p><blockquote><p>蛙类的鲜艳体色是一种防御：它在警告捕食者自己有毒，而不是试图隐藏。</p></blockquote><p><strong>Speaking</strong> He gets defensive whenever anyone mentions his driving, which tells you something.</p><blockquote><p>一有人提他开车他就戒备起来，这本身就说明问题。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>protective</td><td>保护性的</td><td>强调保护对象，不含&quot;戒备&quot;</td></tr><tr><td>wary</td><td>警惕的</td><td>强调小心，未必有敌意</td></tr><tr><td>guarded</td><td>谨慎的</td><td>多形容言辞保守</td></tr><tr><td>aggressive</td><td>攻击性的</td><td>与 defensive 相对</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> de-（离开）+ 拉丁 <em>fendere</em>（击打）→ &quot;把攻击打回去&quot;</li><li><strong>Family:</strong> defend 防御 / defence 防御（英式）/ defendant 被告 / fend off 挡开</li><li><strong>Memory Tip:</strong> fendere 是&quot;打&quot;：defend 打回去（防御）、offend 打到别人身上（冒犯）。一正一反，两个高频词就分清了。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>英式名词 <strong>defence</strong>，美式 defense，形容词统一 defensive。</li><li>&quot;处于守势&quot;是 <strong>on the defensive</strong>，介词固定。</li><li>拼写 defen-sive，不是 <s>defencive</s>。</li></ul></div><div class="vocab-card"><h2 id="undergo" tabindex="-1"><a class="header-anchor" href="#undergo"><span>Undergo</span></a></h2><p class="vc-meta"><strong>/ˌʌndəˈɡəʊ/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>经历，经受（变化、治疗、测试）</li><li>接受（手术、检查）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>undergo a change</td><td>经历变化</td></tr><tr><td>undergo surgery</td><td>接受手术</td></tr><tr><td>undergo testing</td><td>接受检测</td></tr><tr><td>undergo transformation</td><td>经历转变</td></tr><tr><td>undergo stress</td><td>承受压力</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how the landscape underwent change at each stage of the project.</p><blockquote><p>该示意图展示了景观在项目各阶段所经历的变化。</p></blockquote><p><strong>Writing Task 2</strong> Species that undergo a rapid change in habitat rarely adapt in time, however flexible their behaviour appears.</p><blockquote><p>栖息地迅速变化的物种很少能及时适应，无论它们的行为看起来多么灵活。</p></blockquote><p><strong>Speaking</strong> The building underwent a complete renovation and now looks nothing like the photos.</p><blockquote><p>那栋楼彻底翻修过，现在和照片里完全不一样。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>experience</td><td>经历</td><td>更泛，可指正面或中性经历</td></tr><tr><td>suffer</td><td>遭受</td><td>强调负面，带痛苦</td></tr><tr><td>endure</td><td>忍受</td><td>强调持续时间长</td></tr><tr><td>go through</td><td>经历</td><td>口语，最自然</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> under（在下）+ go（走）→ &quot;在下面承受着走过&quot;</li><li><strong>Family:</strong> undergo 经历 / go under 沉没；倒闭 / underlying 潜在的 / undermine 削弱</li><li><strong>Memory Tip:</strong> 字面&quot;从下面走过去&quot;——像顶着重量通过一段路。所以 undergo 的对象多是&quot;需要承受的过程&quot;：手术、检测、变化。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>过去式 <strong>underwent</strong>、过去分词 <strong>undergone</strong>，别按规则动词加 -ed。</li><li>undergo 不用于&quot;经历愉快的事&quot;，那用 experience。</li><li>拼写 under-go，一个词，不分开。</li></ul></div><div class="vocab-card"><h2 id="suffer" tabindex="-1"><a class="header-anchor" href="#suffer"><span>Suffer</span></a></h2><p class="vc-meta"><strong>/ˈsʌfə(r)/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>遭受，受苦（不及物）</li><li>忍受，蒙受（损失、损害）（及物）</li><li>变差，受损（suffer from）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>suffer from ...</td><td>患有……；受……之苦</td></tr><tr><td>suffer damage</td><td>受到损害</td></tr><tr><td>suffer a loss</td><td>遭受损失</td></tr><tr><td>suffer in silence</td><td>默默承受</td></tr><tr><td>suffer the consequences</td><td>承担后果</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how crop yields suffered during the drought years.</p><blockquote><p>该图显示了干旱年份作物产量受损的情况。</p></blockquote><p><strong>Writing Task 2</strong> It is the poorest communities that suffer most when a protected area is created without their consent, which is why consultation is not optional.</p><blockquote><p>在未经同意的情况下设立保护区，受害最深的正是最贫困的社区，因此协商不是可选项。</p></blockquote><p><strong>Speaking</strong> I suffer from terrible hay fever every May, and nothing the pharmacy sells helps.</p><blockquote><p>我每年五月都犯严重的花粉症，药店卖的任何东西都不管用。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>endure</td><td>忍受</td><td>强调坚持、长期承受</td></tr><tr><td>undergo</td><td>经历</td><td>中性，不涉痛苦</td></tr><tr><td>be afflicted by</td><td>受折磨</td><td>书面，多指疾病</td></tr><tr><td>bear</td><td>承担</td><td>强调承受重量或责任</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>sufferre</em>：sub-（在下）+ ferre（承担）→ &quot;在下面扛着&quot;</li><li><strong>Family:</strong> suffering 苦难 / sufferer 患者 / transfer 转移（同源 ferre）/ refer 提及</li><li><strong>Memory Tip:</strong> ferre 是&quot;带、扛&quot;：suffer 在下面扛着、transfer 搬过去、refer 把话带回（提及）。同一词根，画面各有不同。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;患病/受……之苦&quot;用 suffer <strong>from</strong>：suffer <strong>from</strong> asthma ✔ / <s>suffer asthma</s>（虽可及物，但含义偏&quot;忍受&quot;）</li><li>拼写 suf-fer，双 f。</li><li>及物用法多接 damage / loss / consequences，不接人。</li></ul></div><div class="vocab-card"><h2 id="vulnerable" tabindex="-1"><a class="header-anchor" href="#vulnerable"><span>Vulnerable</span></a></h2><p class="vc-meta"><strong>/ˈvʌlnərəbl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>脆弱的，易受伤害的</li><li>易受攻击的；（物种）濒危的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>vulnerable to ...</td><td>易受……影响</td></tr><tr><td>vulnerable species</td><td>易危物种</td></tr><tr><td>the most vulnerable</td><td>最脆弱的群体</td></tr><tr><td>leave sb vulnerable</td><td>使某人处于弱势</td></tr><tr><td>vulnerable habitats</td><td>脆弱栖息地</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows which species are classified as vulnerable in each region.</p><blockquote><p>该图显示了各区域被列为易危的物种。</p></blockquote><p><strong>Writing Task 2</strong> Small populations are genetically vulnerable: with fewer partners to choose from, harmful traits spread instead of being diluted.</p><blockquote><p>小种群在遗传上是脆弱的：可选择的配偶更少，有害性状因此扩散而非被稀释。</p></blockquote><p><strong>Speaking</strong> The chicks are vulnerable for about three weeks, and the whole reserve closes during that time.</p><blockquote><p>雏鸟大约三周内都很脆弱，保护区那段时间整体关闭。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>fragile</td><td>易碎的</td><td>强调结构脆弱、易损坏</td></tr><tr><td>susceptible</td><td>易感的</td><td>学术，多指易受疾病影响</td></tr><tr><td>endangered</td><td>濒危的</td><td>程度更重，数量已极低</td></tr><tr><td>exposed</td><td>暴露的</td><td>强调缺乏遮蔽或保护</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>vulnus</em>（伤口）→ vulnerare（使受伤）</li><li><strong>Family:</strong> vulnerable 易受伤的 / vulnerability 脆弱性 / invulnerable 不可伤害的</li><li><strong>Memory Tip:</strong> 词根 vulnus 是&quot;伤口&quot;——vulnerable 就是&quot;容易被划开口子的&quot;。同族的 invulnerable 加否定前缀 in-，正好作反义对照。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 <strong>to</strong>：vulnerable <strong>to</strong> predation ✔ / <s>vulnerable for</s> ✘</li><li>拼写 vul-ner-able，注意 -ner- 不是 <s>-nar-</s>。</li><li>IUCN 等级里 vulnerable 是&quot;易危&quot;，比 endangered（濒危）轻，别混。</li></ul></div><div class="vocab-card"><h2 id="subsistence" tabindex="-1"><a class="header-anchor" href="#subsistence"><span>Subsistence</span></a></h2><p class="vc-meta"><strong>/səbˈsɪstəns/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>生存，维持生活</li><li>勉强糊口的生活； subsistence farming 自给农业</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>subsistence farming</td><td>自给农业</td></tr><tr><td>subsistence level</td><td>勉强维生的水平</td></tr><tr><td>a means of subsistence</td><td>谋生手段</td></tr><tr><td>below subsistence</td><td>低于生存线</td></tr><tr><td>subsistence hunting</td><td>为生计而狩猎</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how many households depend on subsistence farming in each district.</p><blockquote><p>该图显示了各区有多少家庭依赖自给农业。</p></blockquote><p><strong>Writing Task 2</strong> A ban on hunting may be justified in theory, yet for communities where hunting is subsistence rather than sport, it removes the only safety net they have.</p><blockquote><p>禁猎在理论上或许正当，但对狩猎是生计而非运动的社区来说，这等于拆掉了他们唯一的保障。</p></blockquote><p><strong>Speaking</strong> My grandparents lived at subsistence level for years, and they never described it as poverty.</p><blockquote><p>我祖父母多年勉强维生，他们从不把这称为贫穷。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>livelihood</td><td>生计</td><td>强调收入来源，更常用</td></tr><tr><td>survival</td><td>生存</td><td>强调活下来，不含经济含义</td></tr><tr><td>existence</td><td>存在</td><td>抽象，几乎不指生计</td></tr><tr><td>sustenance</td><td>食物；维持</td><td>书面，多指营养供给</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> sub-（在下）+ 拉丁 <em>sistere</em>（站立）→ &quot;在下面撑住&quot;</li><li><strong>Family:</strong> subsist 维持生存 / subsistence 生计 / consist 组成 / resist 抵抗</li><li><strong>Memory Tip:</strong> sistere 是&quot;站&quot;：subsist 是&quot;在底层站住&quot;，consist 是&quot;站在一起（组成）&quot;，resist 是&quot;站住不退（抵抗）&quot;。一条词根三种站法。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>subsistences</s> ✘</li><li>&quot;自给农业&quot;是 <strong>subsistence farming</strong>，固定搭配。</li><li>与 <strong>sustenance</strong>（食物、营养）区分，两者拼写相近但意思不同。</li></ul></div><div class="vocab-card"><h2 id="exist" tabindex="-1"><a class="header-anchor" href="#exist"><span>Exist</span></a></h2><p class="vc-meta"><strong>/ɪɡˈzɪst/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>存在</li><li>生存，活着（尤指在困境中）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>continue to exist</td><td>继续存在</td></tr><tr><td>exist in ...</td><td>存在于……</td></tr><tr><td>barely exist</td><td>勉强生存</td></tr><tr><td>the right to exist</td><td>生存权</td></tr><tr><td>cease to exist</td><td>不复存在</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows the number of species known to exist in the lake before and after the introduction.</p><blockquote><p>该图显示了引入前后湖中已知存在的物种数量。</p></blockquote><p><strong>Writing Task 2</strong> A species may continue to exist in zoos long after it has ceased to exist in the wild, which raises an awkward question about what &quot;saved&quot; means.</p><blockquote><p>一个物种在野外不复存在之后，仍可能在动物园里继续存在，这就给&quot;被拯救&quot;的含义带来了尴尬的疑问。</p></blockquote><p><strong>Speaking</strong> That café has existed for forty years and still has the same three tables.</p><blockquote><p>那家咖啡馆开了四十年，还是那三张桌子。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>survive</td><td>存活</td><td>强调历经危险仍活着</td></tr><tr><td>persist</td><td>持续</td><td>强调延续不断，可用于抽象</td></tr><tr><td>subsist</td><td>维持生存</td><td>强调勉强糊口</td></tr><tr><td>occur</td><td>存在；发生</td><td>多用于现象、物种分布</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> ex-（向外）+ 拉丁 <em>sistere</em>（站立）→ &quot;站出来、显现&quot;</li><li><strong>Family:</strong> exist 存在 / existence 存在 / coexist 共存 / existential 存在主义的</li><li><strong>Memory Tip:</strong> 与 subsistence 同根 sistere：exist 是&quot;站出来显形&quot;，subsist 是&quot;在下面撑住&quot;。一个显、一个撑，两个词义就分开了。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>exist 是不及物动词，没有被动：<s>is existed</s> ✘</li><li>名词是 <strong>existence</strong>：come into <strong>existence</strong> ✔ / <s>come into exist</s> ✘</li><li>拼写 ex-ist，重音在第二音节 /ɪɡˈzɪst/。</li></ul></div><div class="vocab-card"><h2 id="exterminate" tabindex="-1"><a class="header-anchor" href="#exterminate"><span>Exterminate</span></a></h2><p class="vc-meta"><strong>/ɪkˈstɜːmɪneɪt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>灭绝，彻底消灭（害虫、物种、群体）</li><li>根除（问题）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>exterminate a species</td><td>灭绝一个物种</td></tr><tr><td>be exterminated from ...</td><td>从……被彻底消灭</td></tr><tr><td>exterminate pests</td><td>消灭害虫</td></tr><tr><td>mass extermination</td><td>大规模灭绝</td></tr><tr><td>deliberately exterminate</td><td>蓄意灭绝</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows how the wolf was exterminated from each region between 1850 and 1950.</p><blockquote><p>该图显示了 1850 至 1950 年间狼如何从各地区被彻底消灭。</p></blockquote><p><strong>Writing Task 2</strong> Predators were exterminated because they competed with hunters, and the cost of that decision is still being paid by the ecosystems they once regulated.</p><blockquote><p>捕食者被彻底消灭，因为它们与猎人竞争，而这一决定的代价至今仍由它们曾经调节的生态系统承担。</p></blockquote><p><strong>Speaking</strong> We tried everything to exterminate the ants, and they simply moved to the other side of the kitchen.</p><blockquote><p>我们想尽办法灭蚂蚁，它们干脆搬到了厨房另一边。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>eradicate</td><td>根除</td><td>更书面，多用于疾病、问题</td></tr><tr><td>wipe out</td><td>消灭</td><td>口语，强调彻底性</td></tr><tr><td>eliminate</td><td>消除</td><td>中性，可指逐步排除</td></tr><tr><td>slaughter</td><td>屠杀</td><td>强调大量杀戮，用于动物或人</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> ex-（出）+ 拉丁 <em>terminus</em>（界限）→ &quot;赶出边界&quot;</li><li><strong>Family:</strong> exterminate 灭绝 / terminal 终点 / determine 确定（划定界限）/ terminate 终止</li><li><strong>Memory Tip:</strong> terminus 是&quot;边界&quot;：exterminate 原义&quot;赶出国界&quot;，引申为彻底清除；terminate 是&quot;到边界为止（终止）&quot;，determine 是&quot;划定界限（确定）&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>程度很重，指&quot;彻底消灭&quot;，不要用它替代 reduce / control。</li><li>名词是 <strong>extermination</strong>，不是 <s>exterminate</s>。</li><li>拼写 ex-ter-min-ate，注意中间是 -min-。</li></ul></div><div class="vocab-card"><h2 id="tame" tabindex="-1"><a class="header-anchor" href="#tame"><span>Tame</span></a></h2><p class="vc-meta"><strong>/teɪm/</strong> · adj · 形容词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>驯服的，温顺的（动物）</li><li>平淡的，乏味的（喻）</li><li>驯化，驯服（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a tame animal</td><td>驯服的动物</td></tr><tr><td>tame a wild horse</td><td>驯服一匹野马</td></tr><tr><td>go tame</td><td>变得驯服</td></tr><tr><td>a tame ending</td><td>平淡的结局</td></tr><tr><td>tame the river</td><td>治理河流</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The table compares the behaviour of wild and tame individuals of the same species.</p><blockquote><p>该表比较了同一物种野生个体与驯养个体的行为。</p></blockquote><p><strong>Writing Task 2</strong> A tame animal is not a domesticated one: taming changes an individual, while domestication changes a population over generations.</p><blockquote><p>驯服的动物不等于驯化的动物：驯服改变的是个体，驯化改变的是历经多代的整个种群。</p></blockquote><p><strong>Speaking</strong> The squirrels in this park are so tame they&#39;ll take nuts from your hand, which is exactly the problem.</p><blockquote><p>这个公园的松鼠驯服到会从你手上拿坚果，而这恰恰就是问题。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>domesticated</td><td>驯化的</td><td>指群体经多代人工选择</td></tr><tr><td>docile</td><td>温顺的</td><td>强调性情顺从，不含驯化过程</td></tr><tr><td>gentle</td><td>温和的</td><td>泛指性情柔和</td></tr><tr><td>subdue</td><td>制服</td><td>强调以力量压制</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>tam</em>（驯服的），与拉丁 <em>domare</em>（驯服）同源</li><li><strong>Family:</strong> tame 驯服的 / tamer 驯兽师 / tameness 温顺 / domestic 家养的（同源）</li><li><strong>Memory Tip:</strong> tame 与 domestic 同源——都指向&quot;被带进家里的&quot;。tame 强调个体被驯服，domestic 强调物种被驯化，这一区分在保护生物学写作里很重要。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>tame（个体驯服）≠ domesticated（物种驯化），写作常需区分。</li><li>拼写 tame，别与 <s>time</s> 混。</li><li>形容词&quot;平淡的&quot;多用于批评作品：a <strong>tame</strong> ending ✔</li></ul></div><div class="vocab-card"><h2 id="keeper" tabindex="-1"><a class="header-anchor" href="#keeper"><span>Keeper</span></a></h2><p class="vc-meta"><strong>/ˈkiːpə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>饲养员，管理员（动物园、保护区）</li><li>看守人，保管人</li><li>（足球）守门员（英式 goalkeeper 的简写）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a zoo keeper</td><td>动物园饲养员</td></tr><tr><td>a game keeper</td><td>猎场看守人</td></tr><tr><td>the keeper&#39;s duties</td><td>饲养员的职责</td></tr><tr><td>an animal keeper</td><td>动物管理员</td></tr><tr><td>keeper of the collection</td><td>藏品保管人</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The table shows how keepers divide their working hours between feeding, cleaning and observation.</p><blockquote><p>该表显示了饲养员在喂养、清洁与观察之间的工作时间分配。</p></blockquote><p><strong>Writing Task 2</strong> A good keeper notices a change in appetite before any test confirms illness, which is why experience cannot be replaced by equipment alone.</p><blockquote><p>好的饲养员在任何检测确认疾病之前就能察觉食欲的变化，因此经验无法仅靠设备替代。</p></blockquote><p><strong>Speaking</strong> The keeper explained that the elephant knows her name and reacts to it, which I did not expect.</p><blockquote><p>饲养员说那头大象知道她的名字并且会有反应，这我没料到。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>warden</td><td>管理员</td><td>多指保护区、公园的巡护者</td></tr><tr><td>ranger</td><td>巡护员</td><td>野外巡逻，防偷猎</td></tr><tr><td>carer</td><td>照料者</td><td>强调照护，可用于人</td></tr><tr><td>custodian</td><td>保管人</td><td>正式，多用于藏品、建筑</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> keep（看守、保持）+ -er（人）</li><li><strong>Family:</strong> keep 保持 / keeper 饲养员；守门员 / keepsake 纪念品 / housekeeping 家务管理</li><li><strong>Memory Tip:</strong> keeper 就是&quot;负责让东西保持原样的人&quot;。动物园的 keeper 让动物保持健康，球门的 keeper 让球保持在外——同一个逻辑。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>野生动物巡护员是 <strong>ranger / warden</strong>，不是 keeper（keeper 偏圈养管理）。</li><li>拼写 keep-er，注意双 e。</li><li>&quot;守门员&quot;完整形式 goalkeeper，口语才简写 keeper。</li></ul></div><div class="vocab-card"><h2 id="shepherd" tabindex="-1"><a class="header-anchor" href="#shepherd"><span>Shepherd</span></a></h2><p class="vc-meta"><strong>/ˈʃepəd/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>牧羊人</li><li>引领，护送（动词，像牧人赶羊一样）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a shepherd and his flock</td><td>牧羊人与他的羊群</td></tr><tr><td>shepherd dogs</td><td>牧羊犬</td></tr><tr><td>shepherd sb through ...</td><td>引领某人通过……</td></tr><tr><td>the Good Shepherd</td><td>好牧人（宗教）</td></tr><tr><td>shepherd the visitors</td><td>引导游客</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how a shepherd moves a flock between seasonal pastures.</p><blockquote><p>该示意图展示了牧羊人如何在季节性牧场之间转移羊群。</p></blockquote><p><strong>Writing Task 2</strong> Herders who have shepherded the same slopes for centuries are often the best source of knowledge about how those slopes actually work.</p><blockquote><p>在同一片山坡上放牧了几个世纪的牧民，往往是了解这些山坡如何运作的最佳知识来源。</p></blockquote><p><strong>Speaking</strong> A shepherd walked past with about two hundred sheep and the traffic simply stopped.</p><blockquote><p>一个牧羊人赶着大约两百只羊经过，车流干脆停了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>herder</td><td>牧民</td><td>泛指放牧者，不限羊</td></tr><tr><td>goatherd</td><td>牧山羊人</td><td>专指牧山羊</td></tr><tr><td>drover</td><td>赶畜人</td><td>把牲畜赶往市场的人</td></tr><tr><td>guide</td><td>引导者</td><td>只在引申义上对应</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>scēaphierde</em>：scēap（羊）+ hierde（看守者）</li><li><strong>Family:</strong> shepherd 牧羊人 / sheep 羊 / herd 畜群 / shepherd&#39;s pie 肉馅土豆饼</li><li><strong>Memory Tip:</strong> 字面就是&quot;羊的看守者&quot;（sheep + herd）。shepherd&#39;s pie（牧羊人派）是英国家常菜，用剩羊肉做的，顺手把这个词记牢。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 shep-herd，中间是 ph，不是 <s>shepard</s>。</li><li>泛指放牧者用 <strong>herder</strong>，shepherd 专指牧羊。</li><li>动词引申义&quot;引领、护送&quot;多用于人群：shepherd visitors <strong>through</strong> the site ✔</li></ul></div>`,24)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};